<?php
require_once __DIR__.'/../includes/functions.php'; require_admin(); $adminPage=true; $pageTitle='Admin dashboard';
$counts=['reservations'=>(int)$pdo->query("SELECT COUNT(*) FROM reservations")->fetchColumn(),'pending'=>(int)$pdo->query("SELECT COUNT(*) FROM reservations WHERE status='pending'")->fetchColumn(),'rooms'=>(int)$pdo->query("SELECT COUNT(*) FROM rooms")->fetchColumn(),'customers'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn()];
$recent=$pdo->query("SELECT r.*,u.full_name,rooms.name AS room_name FROM reservations r LEFT JOIN users u ON u.id=r.user_id JOIN rooms ON rooms.id=r.room_id ORDER BY r.created_at DESC LIMIT 8")->fetchAll();
include __DIR__.'/../includes/header.php';
?>
<section class="admin-wrap"><div class="container"><div class="eyebrow mb-3">OneThree management</div><h1 class="section-title mb-4">Admin dashboard.</h1><div class="row g-3 mb-5"><?php foreach(['Total reservations'=>'reservations','Pending requests'=>'pending','Rooms in system'=>'rooms','Customer accounts'=>'customers'] as $label=>$key): ?><div class="col-6 col-lg-3"><div class="stat-card"><div class="muted small"><?= e($label) ?></div><div class="stat-number"><?= $counts[$key] ?></div></div></div><?php endforeach; ?></div><div class="d-flex gap-2 flex-wrap mb-4"><a class="btn btn-outline-gold" href="reservations.php">Manage reservations</a><a class="btn btn-outline-gold" href="rooms.php">Manage rooms</a><a class="btn btn-outline-gold" href="customers.php">View customers</a><a class="btn btn-outline-gold" href="reports.php">Reports</a></div><h2 class="room-name mb-3">Recent reservations</h2><div class="table-responsive"><table class="table table-dark align-middle"><thead><tr><th>Code</th><th>Customer</th><th>Room</th><th>Dates</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><?= e($r['reservation_code']) ?></td><td><?= e($r['guest_name']) ?></td><td><?= e($r['room_name']) ?></td><td><?= e($r['check_in']) ?> → <?= e($r['check_out']) ?></td><td>₱<?= number_format($r['total_amount'],2) ?></td><td><span class="status status-<?= e($r['status']) ?>"><?= e($r['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></div></section>
